fn torneo(valores: &Vec<i32>, i: usize, j: usize, k: usize) -> (usize, usize) {
    let vi = valores[i];
    let vj = valores[j];
    let vk = valores[k];

    // Determine which index holds the maximum value…
    if vi >= vj && vi >= vk {
        // i is at least as large as both j and k
        if vj >= vk {
            (i, j)
        } else {
            (i, k)
        }
    } else if vj >= vi && vj >= vk {
        // j is at least as large as both i and k
        if vi >= vk {
            (j, i)
        } else {
            (j, k)
        }
    } else {
        // k must be the largest
        if vi >= vj {
            (k, i)
        } else {
            (k, j)
        }
    }
}

