    #[test]
    fn test_all_distinct() {
        let v = vec![0, 10, 5, 7, 3];
        // among indices (1,2,3), values are (10,5,7) → pick (1,3)
        assert_eq!(torneo(&v, 1, 2, 3), (1, 3));
    }

    #[test]
    fn test_ties() {
        let v = vec![0, 8, 8, 6];
        // among indices (1,2,3), values (8,8,6) → top two are either (1,2) or (2,1)
        let res = torneo(&v, 1, 2, 3);
        let vals = (v[res.0], v[res.1]);
        assert!(vals.0 >= vals.1);
        assert_eq!(vals, (8, 8));
    }
